class Solution:
    def transformArray(self, nums: List[int]) -> List[int]:
        # Replace even numbers with 0 and odd numbers with 1
        modified_nums = [0 if num % 2 == 0 else 1 for num in nums]
        # Sort the modified list in non-decreasing order
        return sorted(modified_nums)
