from collections import defaultdict
from typing import List

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        # Group indices by their values
        value_positions = defaultdict(list)
        for i, val in enumerate(nums):
            value_positions[val].append(i)

        result = []

        for i, val in enumerate(nums):
            if val not in value_positions:
                result.append(-1)
                continue

            positions = value_positions[val]
            # For each query at index i with value val, find the minimum distance to any other position with the same value
            for j in queries:
                if nums[j] == val:
                    # Calculate circular distance: min(abs(i - j), n - abs(i - j))
                    dist = min(abs(i - j), n - abs(i - j))
                    result.append(dist)
                else:
                    result.append(-1)

        return result
