class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))

        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
            return root_i == root_j

        for i in range(n):
            for j in range(i + 1, n):
                common = 0
                for x in properties[i]:
                    if x in properties[j]:
                        common += 1
                if common >= k:
                    union(i, j)

        components = 0
        for i in range(n):
            if find(i) == i:
                components += 1
        return components
